const run = tools.mcp__symfony_code_mode__execute_tools;
const decode = r => {
  if (r?.structuredContent) return r.structuredContent;
  const t = r?.content?.find?.(c => c.type === 'text')?.text ?? (typeof r === 'string' ? r : JSON.stringify(r));
  try { return JSON.parse(t); } catch { return t; }
};
const out = {order: null, policy: null, denial: null};
try {
  const o = decode(await run({calls:[{name:"refund_get_order", arguments:{orderId:"R-1042"}}]}));
  out.order = o?.results?.[0]?.value ?? o;
  const policyId = out.order?.policyId;
  if (!policyId) throw new Error("No policy ID in order response");
  const p = decode(await run({calls:[{name:"refund_get_policy", arguments:{policyId}}]}));
  out.policy = p?.results?.[0]?.value ?? p;
} catch (e) { out.denial = String(e.message ?? e); }
out

